CREATE SCHEMA falcon_mesh;
COMMENT ON SCHEMA falcon_mesh IS 'falcon_mesh_schema_version=1';

CREATE TABLE falcon_mesh.source_revisions (
  owner_id text NOT NULL CHECK (owner_id ~ '^[a-z0-9_-]{1,64}$'),
  revision_id uuid NOT NULL,
  source_key text NOT NULL,
  source_url text NOT NULL,
  observed_at timestamptz NOT NULL,
  captured_at timestamptz NOT NULL CHECK (captured_at >= observed_at),
  sha256 text NOT NULL CHECK (sha256 ~ '^[a-f0-9]{64}$'),
  content text NOT NULL CHECK (octet_length(content) <= 131072),
  PRIMARY KEY (owner_id, revision_id),
  UNIQUE (owner_id, source_key, revision_id)
);

CREATE TABLE falcon_mesh.source_heads (
  owner_id text NOT NULL,
  source_key text NOT NULL,
  revision_id uuid NOT NULL,
  PRIMARY KEY (owner_id, source_key),
  FOREIGN KEY (owner_id, source_key, revision_id)
    REFERENCES falcon_mesh.source_revisions (owner_id, source_key, revision_id)
);

CREATE TABLE falcon_mesh.analyses (
  owner_id text NOT NULL CHECK (owner_id ~ '^[a-z0-9_-]{1,64}$'),
  id uuid NOT NULL,
  request_id uuid NOT NULL,
  created_at timestamptz NOT NULL,
  observation_id text NOT NULL,
  max_hops smallint NOT NULL CHECK (max_hops BETWEEN 1 AND 3),
  graph jsonb NOT NULL CHECK (jsonb_typeof(graph) = 'object'),
  analysis jsonb NOT NULL CHECK (jsonb_typeof(analysis) = 'object'),
  PRIMARY KEY (owner_id, id),
  UNIQUE (owner_id, request_id)
);

CREATE INDEX analyses_owner_created_at ON falcon_mesh.analyses (owner_id, created_at DESC, id DESC);
DO $$
BEGIN
  IF (SELECT obj_description(oid, 'pg_namespace') FROM pg_namespace WHERE nspname = 'falcon_mesh')
      IS DISTINCT FROM 'falcon_mesh_schema_version=1' THEN
    RAISE EXCEPTION 'Lending migration requires Falcon mesh schema version 1';
  END IF;
END
$$;

CREATE TABLE falcon_mesh.lending_intents (
  owner_id text NOT NULL CHECK (owner_id ~ '^[a-z0-9_-]{1,64}$'),
  id uuid NOT NULL,
  request_id uuid NOT NULL,
  analysis_id uuid NOT NULL,
  created_at timestamptz NOT NULL,
  request jsonb NOT NULL CHECK (jsonb_typeof(request) = 'object' AND octet_length(request::text) <= 4096),
  intent jsonb NOT NULL CHECK (jsonb_typeof(intent) = 'object' AND octet_length(intent::text) <= 1048576),
  PRIMARY KEY (owner_id, id),
  UNIQUE (owner_id, request_id),
  FOREIGN KEY (owner_id, analysis_id) REFERENCES falcon_mesh.analyses (owner_id, id)
);

CREATE TABLE falcon_mesh.lending_events (
  owner_id text NOT NULL CHECK (owner_id ~ '^[a-z0-9_-]{1,64}$'),
  intent_id uuid NOT NULL,
  id uuid NOT NULL,
  request_id uuid NOT NULL,
  created_at timestamptz NOT NULL,
  kind text NOT NULL CHECK (length(kind) <= 16 AND kind IN ('SUBMITTED', 'RECEIPT')),
  data jsonb NOT NULL CHECK (jsonb_typeof(data) = 'object' AND octet_length(data::text) <= 1048576),
  PRIMARY KEY (owner_id, id),
  UNIQUE (owner_id, request_id),
  FOREIGN KEY (owner_id, intent_id) REFERENCES falcon_mesh.lending_intents (owner_id, id)
);

CREATE UNIQUE INDEX lending_events_one_submission ON falcon_mesh.lending_events (owner_id, intent_id)
  WHERE kind = 'SUBMITTED';
CREATE INDEX lending_intents_owner_created ON falcon_mesh.lending_intents (owner_id, created_at DESC, id DESC);
CREATE INDEX lending_events_intent_created ON falcon_mesh.lending_events (owner_id, intent_id, created_at, id);

COMMENT ON SCHEMA falcon_mesh IS 'falcon_mesh_schema_version=2';
CREATE ROLE falcon_mesh_app NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE
  NOREPLICATION NOBYPASSRLS NOINHERIT;

REVOKE ALL ON SCHEMA falcon_mesh FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON ALL TABLES IN SCHEMA falcon_mesh FROM PUBLIC, anon, authenticated, service_role;

GRANT CONNECT ON DATABASE postgres TO falcon_mesh_app;
GRANT USAGE ON SCHEMA falcon_mesh TO falcon_mesh_app;
GRANT SELECT, INSERT ON
  falcon_mesh.source_revisions,
  falcon_mesh.source_heads,
  falcon_mesh.analyses,
  falcon_mesh.lending_intents,
  falcon_mesh.lending_events
TO falcon_mesh_app;
GRANT UPDATE (revision_id) ON falcon_mesh.source_heads TO falcon_mesh_app;
